const a = Symbol('id');
const b = Symbol('id');

console.log(a === b); // false
console.log(typeof a); // "symbol"
console.log(a.description); // "id"
console.log(a.toString()); // "Symbol(id)"

try {
  new Symbol();
} catch (erro) {
  console.log(erro instanceof TypeError); // true
}

const ID_INTERNO = Symbol('idInterno');

function criarUtilizador(nome) {
  return {
    nome,
    [ID_INTERNO]: Date.now(),
  };
}

const utilizador = criarUtilizador('Marta');

console.log(Object.keys(utilizador)); // ['nome']
console.log(JSON.stringify(utilizador)); // {"nome":"Marta"}
console.log(typeof utilizador[ID_INTERNO]); // "number"
console.log(Object.getOwnPropertySymbols(utilizador)); // [Symbol(idInterno)]

