class Intervalo {
  constructor(inicio, fim) {
    this.inicio = inicio;
    this.fim = fim;
  }

  [Symbol.iterator]() {
    let atual = this.inicio;
    const fim = this.fim;

    return {
      next() {
        if (atual <= fim) {
          return { value: atual++, done: false };
        }
        return { value: undefined, done: true };
      },
    };
  }
}

const intervalo = new Intervalo(1, 5);

console.log([...intervalo]); // [1, 2, 3, 4, 5]

for (const numero of intervalo) {
  console.log(numero);
}

class Dinheiro {
  constructor(valor, moeda) {
    this.valor = valor;
    this.moeda = moeda;
  }

  [Symbol.toPrimitive](hint) {
    if (hint === 'number') {
      return this.valor;
    }
    return `${this.valor} ${this.moeda}`; // hint "string" ou "default"
  }
}

const preco = new Dinheiro(19.9, 'EUR');

console.log(`Preço: ${preco}`); // "Preço: 19.9 EUR" (hint "string")
console.log(preco + 10); // 29.9 (hint "default")
console.log(Number(preco)); // 19.9 (hint "number")

class Pilha {
  get [Symbol.toStringTag]() {
    return 'Pilha';
  }
}

console.log(Object.prototype.toString.call(new Pilha())); // "[object Pilha]"

class TipoPar {
  static [Symbol.hasInstance](valor) {
    return typeof valor === 'number' && valor % 2 === 0;
  }
}

console.log(4 instanceof TipoPar); // true
console.log(3 instanceof TipoPar); // false

