function gerarEtiquetas(n) {
  const etiquetas = [];
  for (let i = 0; i < n; i++) {
    etiquetas.push(Symbol(`etiqueta-${i}`));
  }
  return etiquetas;
}

const etiquetas = gerarEtiquetas(3);

const todasDiferentes = etiquetas.every((simbolo, indice) =>
  etiquetas.every((outro, outroIndice) => indice === outroIndice || simbolo !== outro)
);

console.log(todasDiferentes); // true
console.log(etiquetas[0].description); // "etiqueta-0"

const CRIADO_EM = Symbol('criadoEm');

function criarConfig(nome, valor) {
  return {
    nome,
    valor,
    [CRIADO_EM]: Date.now(),
  };
}

const config = criarConfig('tema', 'escuro');

console.log(Object.keys(config)); // ['nome', 'valor']
console.log(JSON.stringify(config)); // {"nome":"tema","valor":"escuro"}
console.log(typeof config[CRIADO_EM]); // "number"
console.log(Object.getOwnPropertySymbols(config)); // [Symbol(criadoEm)]

const moduloA = (() => {
  const MARCA_VALIDA = Symbol.for('app.entidadeValida');

  function criarEntidade(nome) {
    return { nome, [MARCA_VALIDA]: true };
  }

  return { criarEntidade };
})();

const moduloB = (() => {
  function ehEntidadeValida(objeto) {
    const marca = Symbol.for('app.entidadeValida');
    return Boolean(objeto?.[marca]);
  }

  return { ehEntidadeValida };
})();

const entidade = moduloA.criarEntidade('Produto X');
const objetoQualquer = { nome: 'Produto Falso' };

console.log(moduloB.ehEntidadeValida(entidade)); // true
console.log(moduloB.ehEntidadeValida(objetoQualquer)); // false

class CarrinhoCompras {
  #itens = [];

  adicionar(nome, preco) {
    this.#itens.push({ nome, preco });
    return this;
  }

  get total() {
    return this.#itens.reduce((soma, item) => soma + item.preco, 0);
  }

  [Symbol.iterator]() {
    return this.#itens[Symbol.iterator]();
  }

  [Symbol.toPrimitive](hint) {
    if (hint === 'number') {
      return this.total;
    }
    return `Carrinho com ${this.#itens.length} item(ns), total ${this.total}€`;
  }
}

const carrinho = new CarrinhoCompras()
  .adicionar('Teclado', 45)
  .adicionar('Rato', 20);

for (const item of carrinho) {
  console.log(item.nome, item.preco);
}

console.log([...carrinho]); // [{ nome: 'Teclado', preco: 45 }, { nome: 'Rato', preco: 20 }]
console.log(+carrinho); // 65
console.log(`${carrinho}`); // "Carrinho com 2 item(ns), total 65€"
